parts.text:
{
  "units": [
    {
      "quote": "An applicant with a pending name change must not be issued a passport in her/his new name.",
      "scope_quotes": [
        "c. The court order or decree must be final:"
      ],
      "kind": "prohibition",
      "meaning": "Under the rule that a court order or decree must be final, a passport must not be issued in the new name to an applicant whose name change is pending."
    },
    {
      "quote": "See 8 FAM 1001.5 regarding applying for a replacement passport in a new name;",
      "scope_quotes": [
        "c. The court order or decree must be final:",
        "(1) An applicant with a pending name change must not be issued a passport in her/his new name."
      ],
      "kind": "background",
      "meaning": "Cross-reference providing informational guidance to consult 8 FAM 1001.5 regarding applying for a replacement passport in a new name."
    },
    {
      "quote": "An applicant with a pending name change must not be issued a form FS-240 in her/his new name.",
      "scope_quotes": [
        "c. The court order or decree must be final:"
      ],
      "kind": "prohibition",
      "meaning": "Under the rule that a court order or decree must be final, a Form FS-240 must not be issued in the new name to an applicant whose name change is pending."
    },
    {
      "quote": "See 8 FAM 1001.3 regarding amending a form FS-240; and",
      "scope_quotes": [
        "c. The court order or decree must be final:",
        "(2) An applicant with a pending name change must not be issued a form FS-240 in her/his new name."
      ],
      "kind": "background",
      "meaning": "Cross-reference providing informational guidance to consult 8 FAM 1001.3 regarding amending a Form FS-240."
    },
    {
      "quote": "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time.",
      "scope_quotes": [
        "c. The court order or decree must be final:"
      ],
      "kind": "requirement",
      "meaning": "Personnel are required to clear the applicant's pending name regardless of whether the name change is final and regardless of whether the passport is being issued at the present time."
    },
    {
      "quote": "The court order or decree must list both the applicant's current and former name(s).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "A court order or decree submitted for a name change is required to list both the applicant's current name and former name(s)."
    },
    {
      "quote": "You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program).",
      "scope_quotes": [
        "d. The court order or decree must list both the applicant's current and former name(s)."
      ],
      "kind": "condition",
      "meaning": "States the scenario/exception trigger where a court order renders the applicant's former name confidential (such as under California's Safe at Home program)."
    },
    {
      "quote": "When this occurs, the applicant must provide both her/his current and former names on the application.",
      "scope_quotes": [
        "d. The court order or decree must list both the applicant's current and former name(s).",
        "EXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."
      ],
      "kind": "requirement",
      "meaning": "When an applicant provides a court order with a confidential former name, the applicant is required to provide both their current and former names on the passport application."
    },
    {
      "quote": "You may request additional evidence of U.S. citizenship/non-citizen U.S. nationality or identity in accordance with 22 CFR 51.23 and 22 CFR 51.45.",
      "scope_quotes": [
        "d. The court order or decree must list both the applicant's current and former name(s).",
        "EXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."
      ],
      "kind": "permission",
      "meaning": "In confidential former name court order situations, personnel are permitted to request additional evidence of U.S. citizenship/non-citizen U.S. nationality or identity pursuant to 22 CFR 51.23 and 22 CFR 51.45."
    },
    {
      "quote": "8 FAM 403.1-3(B) Name Spacing",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Section heading for guidance on name spacing, conveying no substantive operational rule."
    },
    {
      "quote": "(CT:CITZ-96; 08-04-2023)",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Administrative publication and revision metadata with no substantive operational rule."
    },
    {
      "quote": "In accordance with International Civil Aviation Organization (ICAO) recommendations, U.S. passports, form FS-240, and form DS-2060 are printed in all uppercase letters.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Explains that U.S. passports, Form FS-240, and Form DS-2060 are printed in all uppercase letters following ICAO recommendations."
    },
    {
      "quote": "Printing a name with multiple parts in uppercase letters causes the name to appear as one word unless the parts are separated with spaces.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Explains the technical consequence that multipart names printed in uppercase appear as a single word unless separated by spaces."
    },
    {
      "quote": "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "If an applicant has a multipart name, personnel are obligated to determine how the name will appear on the document."
    },
    {
      "quote": "If the applicant's previous passport had a space, you should add a space on the current application;",
      "scope_quotes": [
        "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"
      ],
      "kind": "recommendation",
      "meaning": "When determining the appearance of a multipart name, if the applicant's previous passport contained a space, personnel are advised to add a space on the current application."
    },
    {
      "quote": "If the applicant does not have a previous passport and the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality or ID has a space, you should add a space on the current application; or",
      "scope_quotes": [
        "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"
      ],
      "kind": "recommendation",
      "meaning": "When determining the appearance of a multipart name, if the applicant lacks a prior passport but their citizenship/nationality evidence or ID has a space, personnel are advised to add a space on the current application."
    },
    {
      "quote": "If the applicant expresses a clear preference to add or remove space, either verbally or in writing, you may add or remove it per the applicant's preference.",
      "scope_quotes": [
        "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"
      ],
      "kind": "permission",
      "meaning": "When determining the appearance of a multipart name, personnel are authorized to add or remove space in accordance with the applicant's stated preference if the applicant communicates a clear preference verbally or in writing."
    },
    {
      "quote": "NOTE: If you receive applications from several family members, you should space the last names consistently, unless a family member expresses a clear preference for a different spacing.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "When receiving applications from multiple family members, personnel should space their last names consistently, except when an individual family member explicitly expresses a preference for different spacing."
    },
    {
      "quote": "NOTE: For special-issuance passports, the spacing of an eligible family member's last name should match the spacing of the last name of the sponsor.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "In the case of special-issuance passports, the spacing of an eligible family member's last name should correspond to the spacing of the sponsor's last name."
    },
    {
      "quote": "Name spacing issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Issues regarding name spacing generally do not justify rewriting a passport, except when the Department failed to follow the applicant's clearly expressed preference."
    },
    {
      "quote": "Arabic ordinal numbers must be changed to Roman numerals, for example, 2nd to II, 3rd to III:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Personnel are required to convert Arabic ordinal numbers in names to Roman numerals (e.g., changing '2nd' to 'II' and '3rd' to 'III')."
    },
    {
      "quote": "Some applicants may include the prefix “Sr.” as an abbreviation for “Señor” in Spanish meaning “Mr.” or “Mister” in English.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Explains that certain applicants use the prefix 'Sr.' to represent the Spanish title 'Señor' ('Mr.' or 'Mister')."
    },
    {
      "quote": "If you determine that this is the case, follow the guidance in 8 FAM 403.1-5(C) regarding ranks and titles.",
      "scope_quotes": [
        "d. Some applicants may include the prefix “Sr.” as an abbreviation for “Señor” in Spanish meaning “Mr.” or “Mister” in English."
      ],
      "kind": "requirement",
      "meaning": "If personnel determine that 'Sr.' is used as an abbreviation for 'Señor' rather than a suffix, they must follow the instructions in 8 FAM 403.1-5(C) covering ranks and titles."
    },
    {
      "quote": "Name suffix issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Name suffix issues are generally not considered sufficient reason to rewrite a passport, except in cases where the Department ignored the applicant's clearly stated preference."
    }
  ]
}
